// scaffold/src/core/billing-order.ts
function exactInstantParts(value) {
  const fraction = /\.(\d+)(?=Z$|[+-]\d{2}:\d{2}$)/;
  const seconds = Date.parse(value.replace(fraction, ""));
  if (!Number.isFinite(seconds)) throw new Error("Invalid billing instant");
  return { seconds, digits: (fraction.exec(value)?.[1] ?? "").replace(/0+$/, "") };
}
function compareExactInstants(left, right) {
  const a = exactInstantParts(left);
  const b = exactInstantParts(right);
  if (a.seconds !== b.seconds) return a.seconds < b.seconds ? -1 : 1;
  return a.digits < b.digits ? -1 : a.digits > b.digits ? 1 : 0;
}
function compareBillingSourceOrder(a, b) {
  if (a.source_order != null && b.source_order != null && a.source_order !== b.source_order) {
    return a.source_order < b.source_order ? -1 : 1;
  }
  return compareExactInstants(a.source_recorded_at, b.source_recorded_at);
}

// scaffold/src/core/reporting-calendar.ts
var ReportingCalendarError = class extends Error {
  constructor(code, message) {
    super(message);
    this.code = code;
  }
};
function reportingCalendarFormatter(calendar) {
  if (!Number.isInteger(calendar.day_boundary_hour) || calendar.day_boundary_hour < 0 || calendar.day_boundary_hour > 23) {
    throw new ReportingCalendarError("invalid_input", "Day boundary hour must be an integer from 0 to 23");
  }
  try {
    if (!calendar.timezone || /^[+-]/.test(calendar.timezone)) throw new Error();
    return new Intl.DateTimeFormat("en-GB", {
      timeZone: calendar.timezone,
      calendar: "gregory",
      numberingSystem: "latn",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23"
    });
  } catch {
    throw new ReportingCalendarError("unsupported_timezone", `Unsupported reporting zone: ${calendar.timezone}`);
  }
}

