// scaffold/src/analytics/catalog/entries/exact-recurring.ts
var EXACT_RECURRING_BLOCKER = "Unavailable until RM-0264 TASK-34/35/36/39/53/54/56 publish complete financial generations, deploy the source Views, and verify lossless registered bindings.";
function exactRecurringMetric(id9, label, economic_basis, population, carrier, column, aggregation, numerator, denominator) {
  const ratio = numerator !== void 0;
  const categories = {
    new_mrr_exact: "new",
    expansion_mrr_exact: "expansion",
    contraction_mrr_exact: "contraction",
    churned_mrr_exact: "churn",
    reactivation_mrr_exact: "reactivation",
    neutral_mrr_exact: "neutral"
  };
  const category = categories[id9.slice("revenue.".length)];
  const predicate = economic_basis !== "selected_recurring_movement" ? "" : id9.includes("transfer_") ? " Atomic basis reads only identity/currency transfer rows; other transfer kinds are explanatory. daily/interval basis reads movement transfer legs only. Never combine both representations." : ` Read row_kind=movement only${category ? `, category=${category}` : ""}; require exactly one movement basis.`;
  return {
    id: id9,
    label,
    value_type: id9.includes("accounts") ? "number" : ratio && !id9.includes("arpa") ? "percent" : "currency",
    source_scope: "total",
    aggregation_semantics: aggregation,
    preferred_analysis_unit: "account",
    direction: /(?:neutral|transfer_(?:in|out))_mrr_exact$/.test(id9) ? "neutral" : /(?:contraction|churned)_mrr_exact$/.test(id9) ? "decrease" : "increase",
    statistical_type: ratio ? "ratio" : id9.includes("accounts") ? "count" : "revenue",
    layer: ratio ? "derived" : "primitive",
    catalog_status: "unavailable",
    accounting: { economic_basis, population },
    ...ratio ? { numerator_metric: numerator, denominator_metric: denominator } : {},
    derivation: {
      carried_by: [carrier],
      input_origin: "none",
      ingested_events: [],
      note: `Exact source projection column ${column}.${predicate} No SQL amount aggregation, rounding or inference from invoices. ${EXACT_RECURRING_BLOCKER}`
    },
    do_not_use_for: "Weekly MRR V1, cash, attributed invoice flow, cross-currency or cross-source totals. Projection rows remain qualified by coverage and selected generation."
  };
}

